async function () {
  try {
    const r = await submitRequest.run();
    const due = new Date(r.due_at).toLocaleString('en-GB', {
      timeZone: 'Asia/Tehran',
      dateStyle: 'medium',
      timeStyle: 'short'
    });
    showAlert(`${r.request_id} created — due ${due} (Tehran)`, 'success');
    resetWidget('frmSubmit', true);
  } catch (e) {
    const body = submitRequest.data || ({});
    if (body.error === 'duplicate_request') {
      showAlert(`You already have an open request with this title: ${body.request_id}`, 'warning');
    } else if (body.error === 'validation_failed') {
      showAlert(`Please check these fields: ${(body.errors || []).map(x => x.field).join(', ')}`, 'error');
    } else {
      showAlert('Could not submit right now. Please try again in a few minutes.', 'error');
    }
  }
}

